INSERT INTO "functions" VALUES(644,398992,33,'Gfx_LinkSpritePackingNode',NULL,'fpo','high','game','reconstructed','decomp/src/geputget.c','698f357becf28ec039300d9e01f27d48f7a04c675486b3506e7ca6107dded174','cdecl; three stack node pointers previous/current/next, caller cleanup 12 bytes; incidental EAX=previous; writable current, nullable neighbors; exact aliases permitted; EBX/ESI/EDI/EBP and stack preserved, DF clear','EXACT','docs/ghidra/windows_gfx_sprite_packing_links.md','Authenticated FPO 33-byte extent and complete twelve-instruction leaf; ordered current.next/current.previous/previous.next/next.previous stores, no node reads/calls; two static callers discard EAX; no packing caller integration or native parity.',NULL);
INSERT INTO "functions" VALUES(645,399040,273,'Gfx_AddSpritePackingBucket',NULL,'fpo','high: complete 273-byte FPO extent/hash, RET/padding, five relocations, full local decoding and Ghidra disassembly/xrefs','game','reconstructed','decomp/src/geputget.c','6da9083d32b7bd4186fb626b6fb5fe0fc099a6d769e332c98805b6d9686700ed','cdecl(int32 requested_extent, GfxSpritePackingNode *initial_page); incidental EAX=published bucket, caller discards; caller cleans 8 bytes; preserves EBX/ESI/EDI/EBP and clear DF','EXACT','docs/ghidra/windows_gfx_sprite_packing_buckets.md','Production C89 reconstructed from authenticated 273-byte Windows extent. Independent raw-offset differential suite: 2734 comparisons, 1140 persistent follow-ups, 127 faults, two 31-read cycle prefixes; real page/gap/link/allocation bodies, CRT malloc modeled. Ordered template/link/table publication, exact arena aliases, live boundary mutations, wrapping arithmetic, normal EAX/stack/nonvolatile/DF ABI and effects before faults compared. Instruction equality, original compiler/link layout and native graphics/heap/game/fault parity unverified; storage/release callers and workspace renderers unreconstructed.',NULL);
INSERT INTO "functions" VALUES(646,399328,85,'Gfx_AddSpritePackingPage',NULL,'fpo','Authenticated 85-byte FPO extent, complete instructions, local hash, relocations and Ghidra callers','game','reconstructed','decomp/src/geputget.c','3e028a97ebd2430f4181d83bd55f460261c9506827cddcee83adce2ea65650b9','No arguments, ordinary RET; incidental pointer EAX is aligned result or reread head; caller ignores result; preserves stack/nonvolatile/DF','EXACT','docs/ghidra/windows_gfx_sprite_packing_pages.md','Production C89 with real allocation dependencies; live head rereads and unchecked failures retained; CRT modeled; callers analysis-only; no native heap or instruction equality',NULL);
INSERT INTO "functions" VALUES(647,399424,47,'Gfx_AllocAlignedBytes',NULL,'fpo','Authenticated FPO, complete instructions, local hash, Ghidra corroboration','game','reconstructed','decomp/src/geputget.c','02150c922745d67bfe77182db1c615fb172490b6f730092ffb3e6c460b3f3b34','cdecl; uint32 size, alignment; pointer EAX; unsigned wrapping arithmetic; unchecked back-pointer store','EXACT','docs/ghidra/windows_gfx_alloc_aligned.md','Production C89; real allocation wrapper and real page caller integration; CRT modeled; unchecked failures preserved; native heap and instruction equality unverified',NULL);
INSERT INTO "functions" VALUES(648,399472,62,'Gfx_FindSpritePackingGap',NULL,'fpo','high: complete 62-byte FPO/hash/instruction extent, localhost Ghidra corroboration and two authenticated caller contracts','game','reconstructed','decomp/src/geputget.c','9fec91b9a7a79937df056da6cea0f29c91ccd4aa4549a1eef45cf0716a71872d','cdecl(int32_t size, GfxSpritePackingNode *first); EAX=0xFFFFFFFF prefix/empty marker, predecessor pointer, or null exhaustion; preserves nonvolatile registers and caller stack','EXACT','docs/ghidra/windows_gfx_sprite_packing_gap.md','Read-only signed packing gap search; modulo-2^32 subtraction; +0/+4/+0x14 node reads; fixed 256 trailing boundary; no pointer/request/cycle guards. Complete packing callers remain analysis-only. Compilation/emulation recorded separately; instruction equality and native runtime unverified.',NULL);
